import functools
@functools.lru_cache(None)
def cut(a, b):
    if a == b: return 0
    return 1 + min([cut(i, b) + cut(a - i, b) for i in range(1, a // 2 + 1)] + [cut(a, j) + cut(a, b - j) for j in range(1, b // 2 + 1)])
def greedy(a, b):
    k = 0
    while a != b:
        if a < b: a, b = b, a
        a -= b; k += 1
    return k
result = cut(3, 5)

